package dev.fallingcloud.slate.core.gfx;

/**
 * Every glyph in {@code assets/slate/textures/gui/icons.png}. GENERATED by {@code tools/icons.py} -
 * edit the glyph list there and regenerate; the atlas is 16 columns of 16x16 cells in ordinal order.
 */
public enum Icon {
    ARROW_LEFT, ARROW_RIGHT, ARROW_UP, ARROW_DOWN, CHEVRON_LEFT, CHEVRON_RIGHT, CHEVRON_UP, CHEVRON_DOWN,
    CLOSE, CHECK, PLUS, MINUS, SEARCH, SETTINGS, FRIENDS, USER,
    CHAT, MIC, MIC_OFF, SPEAKER, SPEAKER_OFF, HEADSET, SCREEN_SHARE, MONITOR,
    CAMERA, IMAGE, FOLDER, WORLD, SERVER, STAR, STAR_FILLED, HEART,
    HEART_FILLED, EDIT, TRASH, COPY, LINK, EXTERNAL, PLAY, PAUSE,
    STOP, REFRESH, FILTER, SORT, GRID, LIST, PIN, LOCK,
    UNLOCK, BELL, BELL_OFF, INFO, WARNING, ERROR, QUESTION, HOME,
    EXIT, POWER, FULLSCREEN, WINDOWED, KEYBOARD, MOUSE, GAMEPAD, LANGUAGE,
    ACCESSIBILITY, PACK, SHADER, CLOUD, MOON, SUN, SPARKLE, BOLT,
    CLOCK, CALENDAR, TAG, BOOKMARK, SEND, ATTACH, GIF, EMOTE,
    VIDEO, DOWNLOAD, UPLOAD, SAVE, UNDO, REDO, LAYERS, MOVE,
    RESIZE, EYE, EYE_OFF, PALETTE, BRUSH, CODE, TERMINAL, BUG,
    WRENCH, SLIDERS, TOGGLE, DOT, DOTS, MENU, DRAG, VOLUME,
    SIGNAL, WIFI, SHIELD, CROWN, TEAM, QUEST, TROPHY, MAP,
    COMPASS, SWORD, BLOCK, SLATE, SINGLEPLAYER, MULTIPLAYER, REALMS, MODS,
    QUIT, BACKUP, DUPLICATE, IMPORT, EXPORT, MUSIC, PING, LAN,
    NEW_WORLD, CHEATS, HARDCORE, CREATIVE, SURVIVAL, ADVENTURE, SPECTATOR, DIFFICULTY,
    GROUP, INVITE, BLOCKED, AWAY, ONLINE, OFFLINE, STREAM, PIP,
    REPLY, REACT, HISTORY, TYPING, MENTION, HASH, PENCIL_OFF, SNAP,
    ALIGN_LEFT, ALIGN_CENTER, ALIGN_RIGHT, ALIGN_TOP, ALIGN_MIDDLE, ALIGN_BOTTOM, TEXT, PANEL,
    SHAPE_STAIRS, SHAPE_SLAB, SHAPE_VSLAB, SHAPE_VSTAIRS, SHAPE_WALL, SHAPE_FENCE, SHAPE_STEP, SHAPE_PANEL,
    SHAPE_GATE, SHAPE_VSTEP, SHAPE_POST, SHAPE_LAYER, SHAPE_PANE, MODE_FILL, MODE_WALLS, MODE_LINE,
    MODE_EXTEND, MODE_HOLLOW, MODE_OUTLINE, MODE_CYLINDER, MODE_SPHERE, MODE_REPLACE, MODE_OVERLAY, MODE_CLEAR,
    MODE_RESHAPE, MODE_PASTE, MODE_CUT, MODE_STACK, MODE_MIRROR, MODE_RADIAL, MODE_MEASURE, TOOLBOX,
    TROWEL, HAMMER, BLUEPRINT, SQUARE, CHISEL, WHEEL, SELECTION, GAMEPLAY,
    CUSTOMIZE, UPG_REACH, UPG_CAPACITY, UPG_SPEED, UPG_MEMORY, UPG_LINK, UPG_MAGNET, UPG_EFFICIENCY;

    public static final int CELL = 16;
    public static final int COLUMNS = 16;

    public int u() { return (ordinal() % COLUMNS) * CELL; }

    public int v() { return (ordinal() / COLUMNS) * CELL; }

    /** Atlas height in cells, for the texture size passed to blit. */
    public static int rows() { return (values().length + COLUMNS - 1) / COLUMNS; }
}
